<?php
declare(strict_types=1);if(PHP_SAPI!=='cli'){http_response_code(404);exit;}$_SERVER['REQUEST_METHOD']='CLI';require_once __DIR__.'/../config/db.php';$c=db();$failed=false;
$checks=[
'sales headers to lines'=>"SELECT COUNT(*) n FROM erp_invoices i LEFT JOIN(SELECT ii.invoice_id,ROUND(SUM(ii.subtotal_tnd),3) ht,ROUND(SUM(ii.montant_tva*i2.exchange_rate),3) vat,ROUND(SUM(ii.total_tnd),3) total FROM erp_invoice_items ii JOIN erp_invoices i2 ON i2.id=ii.invoice_id GROUP BY ii.invoice_id)x ON x.invoice_id=i.id WHERE i.invoice_type IN('FACTURE','AVOIR') AND i.is_validated=1 AND(ABS(ABS(i.subtotal_tnd)-ABS(COALESCE(x.ht,0)))>0.001 OR ABS(ABS(i.montant_tva*i.exchange_rate)-ABS(COALESCE(x.vat,0)))>0.001 OR ABS(ABS(i.total_tnd-i.timbre*i.exchange_rate)-ABS(COALESCE(x.total,0)))>0.001)",
'posted purchases to lines'=>"SELECT COUNT(*) n FROM erp_supplier_invoices si LEFT JOIN(SELECT supplier_invoice_id,ROUND(SUM(total_ht_tnd),3) ht,ROUND(SUM(total_tax_tnd),3) tax,ROUND(SUM(total_ttc_tnd),3) total FROM erp_supplier_invoice_items GROUP BY supplier_invoice_id)x ON x.supplier_invoice_id=si.id WHERE si.status IN('VALIDATED','PARTIALLY_PAID','PAID') AND(ABS(si.total_ht_tnd-COALESCE(x.ht,0))>0.001 OR ABS(si.total_tax_tnd-COALESCE(x.tax,0))>0.001 OR ABS(si.total_ttc_tnd-si.stamp_duty_tnd-COALESCE(x.total,0))>0.001)",
'purchase VAT buckets'=>"SELECT COUNT(*) n FROM erp_supplier_invoice_items sii JOIN erp_supplier_invoices si ON si.id=sii.supplier_invoice_id WHERE si.status IN('VALIDATED','PARTIALLY_PAID','PAID') AND ABS(sii.deductible_vat_tnd+sii.non_deductible_vat_tnd-ROUND(sii.total_vat*si.exchange_rate,3))>0.001",
'customer settlement limits'=>"SELECT COUNT(*) n FROM erp_invoices i LEFT JOIN(SELECT invoice_id,SUM(amount) amount FROM erp_invoice_payments WHERE status='POSTED' GROUP BY invoice_id)p ON p.invoice_id=i.id LEFT JOIN(SELECT invoice_id,SUM(withheld_amount) amount FROM erp_invoice_withholdings WHERE certificate_status IN('RECEIVED','VALIDATED') GROUP BY invoice_id)w ON w.invoice_id=i.id LEFT JOIN(SELECT source_invoice_id,SUM(ABS(total)) amount FROM erp_invoices WHERE invoice_type='AVOIR' AND is_validated=1 GROUP BY source_invoice_id)cr ON cr.source_invoice_id=i.id WHERE i.invoice_type='FACTURE' AND i.is_validated=1 AND COALESCE(p.amount,0)+COALESCE(w.amount,0)+COALESCE(cr.amount,0)-i.total>0.001",
'supplier settlement limits'=>"SELECT COUNT(*) n FROM erp_supplier_invoices si LEFT JOIN(SELECT supplier_invoice_id,SUM(amount) amount FROM erp_supplier_payments WHERE voided_at IS NULL GROUP BY supplier_invoice_id)p ON p.supplier_invoice_id=si.id WHERE si.status IN('VALIDATED','PARTIALLY_PAID','PAID') AND COALESCE(p.amount,0)+si.credited_amount-si.total_ttc>0.001",
'recognized expense values'=>"SELECT COUNT(*) n FROM expense_notes WHERE status IN('APPROVED','REIMBURSED') AND amount<0",
'tenant ownership across report sources'=>"SELECT(SELECT COUNT(*) FROM erp_invoice_items ii JOIN erp_invoices i ON i.id=ii.invoice_id JOIN products p ON p.id=ii.product_id WHERE p.user_id<>i.user_id)+(SELECT COUNT(*) FROM erp_invoice_payments p JOIN erp_invoices i ON i.id=p.invoice_id WHERE p.user_id<>i.user_id)+(SELECT COUNT(*) FROM erp_supplier_payments p JOIN erp_supplier_invoices i ON i.id=p.supplier_invoice_id WHERE p.user_id<>i.user_id) n",
];
$result=[];foreach($checks as $label=>$sql){$n=(int)$c->query($sql)->fetch_assoc()['n'];$result[$label]=$n;if($n){$failed=true;fwrite(STDERR,"FAIL $label: $n mismatch(es)\n");}else echo "PASS $label reconciles\n";}echo json_encode(['success'=>!$failed,'checks'=>$result],JSON_PRETTY_PRINT|JSON_UNESCAPED_SLASHES),"\n";exit($failed?1:0);
